sys_script_include.script:
var VroSeed = Class.create();
VroSeed.prototype = {
  initialize: function () {},
  upsert: function (table, key, rowsJson) {
    var rows = JSON.parse(rowsJson), ids = {}, created = 0, updated = 0;
    for (var i = 0; i < rows.length; i++) {
      var row = rows[i], gr = new GlideRecord(table);
      gr.addQuery(key, row[key]); gr.setLimit(1); gr.query();
      var isNew = !gr.next();
      if (isNew) { gr.initialize(); }
      for (var f in row) { if (row.hasOwnProperty(f)) { gr.setValue(f, row[f]); } }
      var id = isNew ? gr.insert() : gr.update();
      if (!id) { throw new Error("upsert failed on " + table + " " + row[key]); }
      ids[row[key]] = String(id);
      if (isNew) { created++; } else { updated++; }
    }
    return JSON.stringify({ created: created, updated: updated, ids: ids });
  },
  type: "VroSeed"
};
